import unicodedata


def slugify(s):
    s = unicodedata.normalize('NFD', s).lower()
    out = []
    for ch in s:
        if unicodedata.category(ch).startswith('M'):
            # Combining marks (e.g. the tilde on 'õ') are dropped so that
            # accented characters reduce to their base letter.
            continue
        if ch.isalnum():
            out.append(ch)
        else:
            out.append('-')
    s = ''.join(out)
    while '--' in s:
        s = s.replace('--', '-')
    return s.strip('-')
